type FoodItem = { id:string; name:string; aliases?:string[]; category:Category; brand:string; quantity:number|null; unit:Unit; status:"available"|"depleted"|"archived"|"pending"; priority:boolean; location:"冷冻"|"冷藏"|"常温"|""; nutrition:{basisAmount:number; basisUnit:Unit; kcal:number|null; protein:number|null; carbs:number|null; fat:number|null; source:"label"|"recipe"|"estimate"|"unknown"; sourceNote:string; sourceText:string; nutrientSources?:Partial<Record<"kcal"|"protein"|"carbs"|"fat","label"|"recipe"|"estimate"|"unknown">>}; gramsPerUnit:number|null; ingredients:string; supplementFacts:string; notes:string; confirmedAt:string; updatedAt:string };
