 const [edit,setEdit]=useState<FoodItem|null>(null),[consume,setConsume]=useState<FoodItem|null>(null),[prefsOpen,setPrefsOpen]=useState(false),[prefs,setPrefs]=useState(""),[prefsDirty,setPrefsDirty]=useState(false);
 const [restore,setRestore]=useState<{items:FoodItem[];preferences:string[]}|null>(null),[cancelPlan,setCancelPlan]=useState<Plan|null>(null);const importRef=useRef<HTMLInputElement>(null);
 const stateRef=useRef<InventoryState|null>(null),savingRef=useRef(false),conflictRef=useRef(false),checkBlockedRef=useRef(false),checkChain=useRef<Promise<unknown>>(Promise.resolve()),ownCheckRevisions=useRef(new Set<number>());
 async function load(){setLoading(true);setError("");try{const response=await fetch("/api/inventory",{cache:"no-store"});const data=await response.json() as ApiResponse;if(response.status===401)setAuth(true);if(!response.ok)throw new Error(data.error||uiText("Unable to read inventory. Try again."));setAuth(false);if(data.state.revision>=(stateRef.current?.revision??0)){stateRef.current=data.state;setState(data.state);}conflictRef.current=false;checkBlockedRef.current=false;setConflict(false);if(!prefsDirty)setPrefs(data.state.preferences.join("\n"));}catch(cause){setError(cause instanceof Error?uiText(cause.message):uiText("Inventory could not be loaded. Try again."));}finally{setLoading(false);}}
 useEffect(()=>{void load();},[]);// eslint-disable-line react-hooks/exhaustive-deps
 useEffect(()=>{if(!notice)return;const timer=setTimeout(()=>setNotice(""),4500);return()=>clearTimeout(timer);},[notice]);
 async function performMutation(action:string,payload:Record<string,unknown>,success:string){const current=stateRef.current;if(!current||savingRef.current||conflictRef.current)return {ok:false,revision:current?.revision??0};savingRef.current=true;setSaving(true);setError("");try{const response=await fetch("/api/inventory",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({operationId:crypto.randomUUID(),expectedRevision:current.revision,action,...payload})});const data=await response.json() as ApiResponse;if(response.status===401)setAuth(true);if(response.status===409){conflictRef.current=true;setConflict(true);throw new Error(data.error||uiText("Inventory changed on another page. Refresh, review and save your changes again."));}if(!response.ok)throw new Error(data.error||uiText("Saving failed. Try again."));if(data.state.revision>=(stateRef.current?.revision??0)){stateRef.current=data.state;setState(data.state);}if(action==='set_daily_supplement_check'&&data.state.revision===current.revision+1)ownCheckRevisions.current.add(data.state.revision);if(success)setNotice(success);return {ok:true,revision:data.state.revision};}catch(cause){setError(cause instanceof Error?uiText(cause.message):uiText("Saving failed. Refresh to check whether it was saved."));return {ok:false,revision:stateRef.current?.revision??0};}finally{savingRef.current=false;setSaving(false);}}
 async function mutate(action:string,payload:Record<string,unknown>,success:string){return (await performMutation(action,payload,success)).ok;}
 function dispatchSupplementCheck(payload:{date:string;doseId:string;checked:boolean;expectedRevision:number},message:string){const task=checkChain.current.then(async()=>{const current=stateRef.current;if(!current||checkBlockedRef.current)return {ok:false,revision:current?.revision??0};let ownAdvance=payload.expectedRevision<=current.revision;for(let rev=payload.expectedRevision+1;ownAdvance&&rev<=current.revision;rev++)ownAdvance=ownCheckRevisions.current.has(rev);if(!ownAdvance){checkBlockedRef.current=true;setError(uiText("Supplement records changed elsewhere. Refresh and review before checking again."));return {ok:false,revision:current.revision};}const result=await performMutation('set_daily_supplement_check',{...payload,expectedRevision:current.revision},'');if(!result.ok)checkBlockedRef.current=true;return result;});checkChain.current=task.catch(()=>undefined);return task;}
 const allItems=state?.items??[];
