 function exportBackup(){if(!state)return;const url=URL.createObjectURL(new Blob([JSON.stringify({exportedAt:new Date().toISOString(),state},null,2)],{type:"application/json"}));const link=document.createElement("a");link.href=url;link.download=`${uiText("daily-pantry-")}${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(url);setNotice(uiText("Inventory backup exported"));}
 async function importBackup(file:File|undefined){if(!file)return;try{if(file.size>2_000_000)throw new Error(uiText("Choose a JSON backup smaller than 2 MB."));const data=JSON.parse(await file.text()),backup=data.state||data;if(!Array.isArray(backup.items)||!Array.isArray(backup.preferences)||!backup.preferences.every((value:unknown)=>typeof value==="string"))throw new Error(uiText("Invalid backup. Food items and preferences are required."));setRestore({items:backup.items,preferences:backup.preferences});}catch(cause){setError(cause instanceof Error?uiText(cause.message):uiText("Unable to read the backup file."));}if(importRef.current)importRef.current.value="";}
