 function openEdit(item:FoodItem){const current=stateRef.current;setEditRevision(current?.revision??null);setEdit(structuredClone(current?.items.find(existing=>existing.id===item.id)??item));}
 function openRestock(item:FoodItem){const current=stateRef.current,latest=current?.items.find(existing=>existing.id===item.id);if(!latest){setError(uiText("This inventory item changed. Refresh before selecting it for restocking."));return;}setRestockRevision(current?.revision??null);setEdit(null);setRestock(structuredClone(latest));}
 function openCalibrate(item:FoodItem){const current=stateRef.current,latest=current?.items.find(existing=>existing.id===item.id);if(!current||!latest){setError(uiText("This inventory item changed. Refresh before reviewing its balance."));return;}try{setCalibrate({item:structuredClone(latest),revision:current.revision,preview:previewFoodBalanceReconciliation(current,latest.id)});}catch(cause){setError(cause instanceof Error?uiText(cause.message):uiText("Unable to reconcile recorded intake. Refresh and try again."));}}
